scenarios.example_code:
import { installConnector } from '@projexlight/connector-jira';
const { install_id } = await installConnector({
  tenant_id, site_url: 'acme.atlassian.net', auth_code,
});

subscribeEvents('workflow.run.started.v1', async (e) => {
  if (e.payload.workflow_id !== 'engineering-tasks') return;
  await createJiraIssue({ tenant_id: e.tenant_id, project_key: 'ACME', issue_type: 'Story', summary: e.payload.title });
});

import { registerBinding } from '@projexlight/connector-jira';
await registerBinding({
  install_id, projex_entity: 'sdk-projection.sprint',
  jira_object: 'Sprint', direction: 'pull', cadence_min: 60,
});

import { handleWebhook } from '@projexlight/connector-jira';
await handleWebhook({
  tenant_id, signature, body, event_type: 'jira:issue_updated',
});
